public class BusiestBusRow { static int[] busiestRow(int[][] grid){int row=0,best=-1;for(int i=0;i<grid.length;i++){int total=0;for(int seat:grid[i])total+=seat;if(total>best){best=total;row=i;}}return new int[]{row,best};} public static void main(String[]args){int[] result=busiestRow(new int[][]{{2,0,1},{3,3,1},{1,1,1}});System.out.println("Row "+result[0]+", Total "+result[1]);} }
